def parse_records(rows):
    out=[]
    for row in rows:
        if type(row.get('id')) is not int or not isinstance(row.get('name'),str):
            raise ValueError('invalid_required_field')
        if set(row)-{'id','name'}:
            raise ValueError('unknown_field')
        out.append(dict(row))
    return out
